#pragma once

// First-hit delay (load time) per card, in ticks: the windup before a unit's
// first hit on a target, and before every hit after a retarget. Generated by
// bot-77's scripts/sim_load_times.py from RoyaleAPI cr-api-data (public
// game-file extracts, last updated 2023-12): cards_stats_troop.json's
// summon_character -> cards_stats_characters.json / cards_stats_building.json
// load_time (ms). Cards not listed (spells, evolutions, unmatched) have none.
inline int loadTicksForCard(int cardId) {
    switch (cardId) {
        case 0: return 7;  // Knight (Knight: 700 ms of 1200 ms)
        case 1: return 4;  // Archers (Archer: 400 ms of 900 ms)
        case 2: return 10;  // Giant (Giant: 1000 ms of 1500 ms)
        case 4: return 7;  // Goblins (Goblin: 700 ms of 1100 ms)
        case 5: return 11;  // Mini PEKKA (MiniPekka: 1100 ms of 1600 ms)
        case 6: return 2;  // Musketeer (Musketeer: 200 ms of 1000 ms)
        case 8: return 9;  // Barbarians (Barbarian: 900 ms of 1300 ms)
        case 9: return 16;  // Bomber (Bomber: 1600 ms of 1800 ms)
        case 10: return 14;  // Valkyrie (Valkyrie: 1400 ms of 1500 ms)
        case 11: return 10;  // Wizard (Wizard: 1000 ms of 1400 ms)
        case 12: return 5;  // Skeleton Army (Skeleton: 500 ms of 1000 ms)
        case 13: return 13;  // P.E.K.K.A. (Pekka: 1300 ms of 1800 ms)
        case 14: return 9;  // Prince (Prince: 900 ms of 1400 ms)
        case 15: return 10;  // Hog Rider (HogRider: 1000 ms of 1600 ms)
        case 17: return 9;  // Elite Barbarians (AngryBarbarian: 900 ms of 1400 ms)
        case 18: return 8;  // Royal Giant (RoyalGiant: 800 ms of 1700 ms)
        case 19: return 15;  // Golem (Golem: 1500 ms of 2500 ms)
        case 20: return 4;  // Dart Goblin (BlowdartGoblin: 350 ms of 700 ms)
        case 21: return 4;  // Lumberjack (RageBarbarian: 400 ms of 800 ms)
        case 22: return 20;  // Bowler (Bowler: 2000 ms of 2500 ms)
        case 23: return 12;  // Spear Goblins (SpearGoblin: 1200 ms of 1700 ms)
        case 24: return 5;  // Skeletons (Skeleton: 500 ms of 1000 ms)
        case 25: return 0;  // Cannon (Cannon: 0 ms of 900 ms)
        case 26: return 7;  // Tesla (Tesla: 700 ms of 1100 ms)
        case 27: return 11;  // Bomb Tower (BombTower: 1100 ms of 1600 ms)
        case 28: return 12;  // Inferno Tower (InfernoTower: 1200 ms of 400 ms)
        case 34: return 12;  // Ice Wizard (IceWizard: 1200 ms of 1700 ms)
        case 35: return 12;  // Electro Wizard (ElectroWizard: 1200 ms of 1800 ms)
        case 36: return 4;  // Executioner (AxeMan: 400 ms of 900 ms)
        case 39: return 11;  // Giant Skeleton (GiantSkeleton: 1100 ms of 1400 ms)
        case 40: return 15;  // Ice Golem (IceGolemite: 1500 ms of 2500 ms)
        case 41: return 5;  // Minions (Minion: 500 ms of 1000 ms)
        case 42: return 5;  // Minion Horde (Minion: 500 ms of 1000 ms)
        case 43: return 11;  // Mega Minion (MegaMinion: 1100 ms of 1500 ms)
        case 44: return 12;  // Baby Dragon (BabyDragon: 1200 ms of 1500 ms)
        case 45: return 18;  // Balloon (Balloon: 1800 ms of 2000 ms)
        case 46: return 9;  // Dark Prince (DarkPrince: 900 ms of 1300 ms)
        case 47: return 12;  // Royal Ghost (Ghost: 1200 ms of 1800 ms)
        case 48: return 12;  // Mega Knight (MegaKnight: 1200 ms of 1700 ms)
        case 49: return 16;  // Battle Healer (client battle_healer.toml 2026-10-28: 1600 ms of 2000 ms)
        case 50: return 6;  // Bandit (Assassin: 600 ms of 1000 ms)
        case 52: return 7;  // Miner (Miner: 700 ms of 1200 ms)
        case 53: return 12;  // Fisherman (Fisherman: 1200 ms of 1300 ms)
        case 56: return 12;  // Inferno Dragon (InfernoDragon: 1200 ms of 400 ms)
        case 57: return 14;  // Electro Dragon (ElectroDragon: 1400 ms of 2100 ms)
        case 58: return 6;  // Night Witch (DarkWitch: 550 ms of 1300 ms)
        case 59: return 5;  // Phoenix (Phoenix: 500 ms of 1000 ms)
        case 60: return 30;  // Sparky (ZapMachine: 3000 ms of 4000 ms)
        case 61: return 25;  // Princess (Princess: 2500 ms of 3000 ms)
        case 62: return 15;  // Hunter (client hunter.toml 2026-10-28: 1500 ms of 2200 ms)
        case 63: return 6;  // Magic Archer (EliteArcher: 600 ms of 1100 ms)
        case 64: return 24;  // Firecracker (Firecracker: 2350 ms of 3000 ms)
        case 65: return 15;  // Skeleton Dragons (SkeletonDragon: 1500 ms of 1900 ms)
        case 67: return 6;  // Flying Machine (DartBarrell: 600 ms of 1100 ms)
        case 68: return 7;  // Mother Witch (WitchMother: 700 ms of 1000 ms)
        case 69: return 4;  // Cannon Cart (MovingCannon: 400 ms of 1000 ms)
        case 70: return 0;  // Furnace (FirespiritHut: 0 ms of 6000 ms)
        case 71: return 4;  // Witch (Witch: 400 ms of 1100 ms)
        case 72: return 1;  // Ice Spirit (IceSpirits: 100 ms of 300 ms)
        case 73: return 1;  // Fire Spirit (FireSpirits: 100 ms of 300 ms)
        case 75: return 1;  // Electro Spirit (ElectroSpirit: 100 ms of 300 ms)
        case 76: return 6;  // Guards (SkeletonWarrior: 600 ms of 1000 ms)
        case 77: return 8;  // Royal Recruits (Recruit: 800 ms of 1300 ms)
        case 78: return 7;  // Bats (Bat: 700 ms of 1300 ms)
        case 79: return 10;  // Zappies (MiniZapMachine: 1000 ms of 2100 ms)
        case 80: return 7;  // Three Musketeers (client three_musketeer_rework.toml 2026-10-28: 700 ms of 1300 ms)
        case 81: return 0;  // Battle Ram (BattleRam: 50 ms of 400 ms)
        case 82: return 8;  // Royal Hogs (RoyalHog: 800 ms of 1200 ms)
        case 83: return 10;  // Wall Breakers (Wallbreaker: 1000 ms of 1200 ms)
        case 84: return 6;  // Electro Giant (ElectroGiant: 600 ms of 2100 ms)
        case 87: return 12;  // Ram Rider (Ram: 1200 ms of 1800 ms)
        case 88: return 7;  // Goblin Giant (GoblinGiant: 700 ms of 1500 ms)
        case 89: return 2;  // Skeleton Barrel (SkeletonBalloon: 200 ms of 300 ms)
        case 90: return 3;  // Elixir Golem (ElixirGolem1: 300 ms of 1100 ms)
        case 91: return 3;  // Lava Hound (LavaHound: 300 ms of 1300 ms)
        case 92: return 0;  // X-Bow (Xbow: 0 ms of 300 ms)
        case 93: return 40;  // Mortar (Mortar: 4000 ms of 5000 ms)
        case 94: return 0;  // Barbarian Hut (BarbarianHut: 0 ms of 10000 ms)
        case 95: return 0;  // Goblin Hut (GoblinHut: 0 ms of 10000 ms)
        case 96: return 0;  // Tombstone (Tombstone: 0 ms of 10000 ms)
        case 97: return 0;  // Goblin Cage (GoblinCage: 0 ms of 10000 ms)
        case 98: return 2;  // Goblin Drill (GoblinDrill: 200 ms of 1100 ms)
        case 112: return 7;  // Goblin Gang (Goblin: 700 ms of 1100 ms)
        case 113: return 11;  // Rascals (RascalBoy: 1100 ms of 1500 ms)
        case 115: return 7;  // Mighty Miner (MightyMiner: 700 ms of 400 ms)
        case 116: return 7;  // Golden Knight (GoldenKnight: 700 ms of 900 ms)
        case 117: return 13;  // Skeleton King (SkeletonKing: 1300 ms of 1600 ms)
        case 118: return 9;  // Archer Queen (ArcherQueen: 900 ms of 1200 ms)
        case 119: return 6;  // Monk (Monk: 600 ms of 800 ms)
        case 166: return 7;  // Hero Knight (Knight: 700 ms of 1200 ms)
        case 167: return 10;  // Hero Wizard (Wizard: 1000 ms of 1400 ms)
        case 168: return 2;  // Hero Musketeer (Musketeer: 200 ms of 1000 ms)
        case 169: return 10;  // Hero Giant (Giant: 1000 ms of 1500 ms)
        case 170: return 11;  // Hero Mini P.E.K.K.A. (MiniPekka: 1100 ms of 1600 ms)
        case 171: return 6;  // Hero Magic Archer (EliteArcher: 600 ms of 1100 ms)
        case 172: return 7;  // Hero Goblins (Goblin: 700 ms of 1100 ms)
        case 173: return 11;  // Hero Mega Minion (MegaMinion: 1100 ms of 1500 ms)
        case 175: return 15;  // Hero Ice Golem (IceGolemite: 1500 ms of 2500 ms)
        default: return 0;
    }
}
